/* ★★★ 出口判据②（兜底）：圈内【持续丢线】= 出圈（2026-09-23 新增）★★★
   为什么加它：判据①（`11000000` 图案）是用户实测的，但用户也说它
              "时间窗口很短，可能只是闪了一下"。若它压根不出现，就永远出不去。

   为什么"圈内持续丢线"≈出口：
     · 葫芦圈【内】传感器一直能看到某种图案（哪怕是零散的分离图案），
       `line_lost`（连续 LOST_SPIN_DELAY+ 拍全灭）基本不会被置起来。
     · 等绕到最后一个圆结束、线没了 → 才会出现"连续好几拍全灭" → 这就是出口。
   所以"已经进过圈(IG=1) + 持续丢线"几乎是出口的**专属**信号，
   而且【完全不依赖任何具体图案】—— 这正是它的价值。

   1 = 启用（推荐，当前）；0 = 只用图案判据①
   ★如果发现"在葫芦圈里还没走完就突然右转"（圈内某处被误判成丢线）→ 改 0。

   ★★★ 2026-10-08（1008-R18）【改为 1：实车数据支持它，而且是"出口"唯一干净的信号】★★★
   数据：跑完葫芦圈、卡在最后一个节点那一趟，黑匣子 6.5 秒窗口里
     128 帧【线一直可见】（IR 全部非 0），到该出圈那一刻 IR 直接变 00000000（线到头了）。
     ⇒ 圈内【没有】出现过"持续丢线"，所以这条判据在这一趟里零误报；
       而图案判据（①）在节点上误触发了一次，把 ONE_SHOT 锁死，反而让真出口转不了。
   保险：它同时要求 ge_in_gourd（进圈印记，实测长期成立）+ 连续丢线超过 LOST_SPIN_DELAY，
     不是"闪一下全灭"就算 —— 直角弯/十字不会有"圈内印记 + 持续全灭"这个组合。 */
#define GOURD_EXIT_ON_LOST   0   /* ★R25：关掉。理由见下方 R25 注释 */

/* ★★ 出口判据：滑动窗口累加（2026-09-23 改，解决"只闪一下"）★★
   用户实测："出葫芦圈的那个特征虽然比较明显，但时间窗口很短，可能只是闪了一下"

   为什么原来会漏：原来是【连续 CONFIRM 拍】才算数 →
                  若特征只闪 1 拍（10ms），CONFIRM=2 永远抓不到。
   ★顺带说明：过采样【救不了】这个 —— 8 次子采样只覆盖 9.8µs，
     而 1 拍是 10ms，只占 0.1%。过采样只能压"拍内抖动"，抓不到"跨拍闪烁"。

   现在改成：WINDOW 拍这个窗口内【累计】命中 CONFIRM 次就触发。
            亮→灭→亮 这种闪断也能累加，不再被清零。
   ⚠️ 代价：CONFIRM=1 更容易误触发 →
      所以必须配合下面的 GOURD_EXIT_REQUIRE_ENTRY（只允许"进过圈"的车出圈转向）。 */
#define GOURD_EXIT_CONFIRM   1      /* 窗口内累计命中几次就触发。★1 = 闪一下也抓得住 */
#define GOURD_EXIT_WINDOW    8      /* 滑动窗口拍数（8 拍 = 80ms）。窗口内累加 */
#define GOURD_EXIT_TURN_PWM  0      /* 右转差速幅度（左轮 = sp_curve + 此值, 右轮 = −）
                                       ★2026-09-23 12V: 55×0.74 = 41
                                         （不缩的话 12V 下这个急转会暴力很多 →
                                           转过头会更严重，刚调好的 50° 就白调了）*/
#define GOURD_EXIT_COOLDOWN  40     /* 转完后的冷却拍数（40 拍 = 400ms），防连环触发 */

/* ★★ 进圈闸门（2026-09-23 新增）★★ —— 强烈建议保留
   出圈特征"只闪一下"→ 只能把确认放宽到 1 次 → 误触发风险上升。
   而**右直角弯入口的图案也是"只有最左两路亮"**（两者静态位图完全一样）。
   所以加一道闸门：**没进过葫芦圈就不许出圈转向**。

   做法：用【已实车验证过的 4 个进圈图案】打"进过圈"印记：
             11100110  10110010  11110010  11001110
         印记在进圈图案没再出现后的 GOURD_ENTRY_MARK_TTL 拍内保持，然后清除。
   1 = 启用（推荐，当前）;  0 = 关掉（回到"看到左两路亮就转"）
   ★若"出圈该转却没转"（印记提前清了）→ 把 TTL 加大。 */
#define GOURD_EXIT_REQUIRE_ENTRY 1
/* ★★★ 2026-10-08（1008-R20）让"进过圈"这个状态活过整趟 ★★★
 *  【实车证据】R19 那趟跑完从芯片读出来：ge_in_gourd = **0**
 *    —— 车明明在圈里绕第 2 个圈，固件却认为"不在葫芦圈里"。后果是全方位的：
 *      · 分支口模式（R19 的门要它）= 圈内真切点也不接管 ⇒ 车自己硬拐 ⇒ 卡在圈上 ✗
 *      · 出圈判据②（"圈内持续丢线"要它）= 永远不许出圈（那趟 GE=0 正是如此）✗
 *      · 相切点计数 GW 也一直 0 ✗
 *  【为什么会掉】原判据是"连续 100 拍（1 秒）普通线 ⇒ 判定离开葫芦圈"。
 *    可葫芦圈里【两段切线之间本来就是普通线跟车】，只要超过 1 秒就自己把印记清了 ✗✗。
 *  【改法】把两个"保险"都放宽到"活过整趟"：
 *    · GOURD_ENTRY_CLEAR_FRAMES 100 → 3000（30 秒普通线才算真出去）
 *    · GOURD_ENTRY_MARK_TTL     600 → 6000（60 秒强制清，仍然留着当最后保险）
 *  【风险与依据】放宽后，万一印记被误点亮（例如陀螺判据在直角弯误触发），
 *    它会一直留着 ⇒ 圈外也可能允许分支口/出圈。但实测两趟都表明：
 *      · 那个直角弯误触发那一拍（f=8、IR:11111000）**IG 恰好是 0**，图案不是 4 个进圈图案之一；
 *      · 陀螺判据（GOURD_IG_SUM_TH）在普通线跟车时（GZ≈0~90）也够不到阈值。
 *    ⇒ 目前没有观察到"圈外把印记点亮"的实例；先按"活过整趟"用，
 *      若真的出现"圈外乱出圈"，再回来收紧这两条。
 *  ★回退：两条都改回 100 / 600。 */
#define GOURD_ENTRY_CLEAR_FRAMES 200/* ★R21 起改回 100（R20 曾改成 3000）：闸门已换成【里程】，
                                       不再需要它"活过整趟"；留着反而是"误置位后无法纠正"的风险源。
                                       ★离开葫芦圈的判据：连续这么多拍是"普通线"(200ms)。
                                       "普通线" = 连续一小片亮、中间没有暗缝
                                                 (亮路数 1~4 且 最左~最右之间无空隙)。
                                       葫芦圈里传感器一直看到"有暗缝的分离图案";
                                       出圈后就是普通的一条线 → 用这个判定"已出圈"。
                                       ★这个值是主判据，别乱动。 */
#define GOURD_ENTRY_MARK_TTL 600    /* ★R21 起改回 600（R20 曾 6000）；理由同上：闸门已换成【里程】 */    /* ★只当【保险】：万一卡在圈里一直不出现普通线，
                                       最多这么多拍后强制清除印记（600 拍 = 6 秒），
                                       防止印记永久卡住导致"第二圈不再触发出圈"。
                                       ★注意：它【不是】主判据 ——
                                         取小会在圆圈之间误清（锁存失效、波浪中途多次转），
                                         取大又会让整圈清不掉（第二圈不触发）。
                                         两种失效都被仿真复现过，所以才改成"只看普通线"。 */

/* ★★★ 葫芦圈内【屏蔽丢线兜底】（2026-09-23 新增）★★★
   问题（用户实测）："过葫芦圈的时候防丢线机制经常干扰小车的运动，
                     但它在除了葫芦圈以外的地方又确实挺有用。"

   为什么会干扰：葫芦圈里传感器【一直】看到"有暗缝的分离图案"（圆与圆之间的缝隙、
                蛇行波浪的拐点），丢线机制会把它误判成"找不到线" →
                先加倍修正、再原地旋转找线 → 把车从赛道上拽走。
                而圈外它确实有用（直角弯"从冲出去回不来"变成"原地转一下找到线"）。

   解法：用【进圈印记】区分两种场景 —— 圈内屏蔽、圈外保留。
        （进圈印记已经在维护，直接复用，不用另造判据。）

   屏蔽期间丢线怎么表现：
      1 = 保持上一拍的 error（冻结修正方向，按当前航向继续走）  ← 推荐
      2 = 滑行直行（error 归零）
      3 = 不处理（原样交给 PD，用当前帧 error —— 通常是 0，因为全灭时 error=0） */
#define USE_GOURD_LOST_GUARD 0
#define GOURD_LOST_MODE      1

/* ★★★ "是否在葫芦圈里"的判据换掉了（2026-09-23，实车数据驱动）★★★
   用户实车日志（FW:0923-3000）证明：**原来那 4 个硬编码进圈图案一次都没匹配上**
   （整段葫芦圈里 `IG=0` 全程），导致依赖它的三件事全没生效：
       出圈闸门 / 出圈锁存 / 圈内丢线屏蔽。
   车当时实际看到的是 `00110000 01110000 00111000 00000110 00000011 10011000 ...`
   —— 和 `11100110` 那 4 个完全不同（那 4 个是另一次/另一处的实拍）。

   → 换成【几何判据】：葫芦圈是蛇行波浪 = 车【持续在转弯】→ 偏航率 |GZ| 长期很大；
     而直线段 |GZ| 只有噪声级（±50 左右）。

   用用户同一份日志的 GZ 序列实测验证（见 _work/ig_detect.js）：
       窗口 20 拍内 sum(|GZ|)： 直线段最大 **448**   葫芦圈最小 **12542**
       → **28 倍余量**，阈值取 4000 有 9 倍安全边际（直角弯也不会误触发）。

   1 = 用角速度判据（推荐，当前）
   0 = 退回"4 个硬编码图案"（旧行为，实测无效，仅留作对照） */
#define USE_GOURD_IG_GYRO    1
#define GOURD_IG_WINDOW      10    /* 滑动窗口拍数（10 拍 = 100ms）。
                                      ★参数是【扫出来的】不是拍脑袋的（见 _work/ig_pick.js）：
                                        窗口越大 → 延迟越大（要等窗口填满强信号）。
                                        W=6 延迟 5 拍但边际只有 2.46 倍；
                                        W=10 延迟 6 拍、边际 3.79 倍 ← 只慢 1 拍，边际最好。 */
#define GOURD_IG_SUM_TH      1000  /* ★【进圈】阈值。窗口内 sum(|GZ|) 超过它就认为"在葫芦圈里"。
                                     实测（用户 FW:0923-3000 日志的 GZ 序列）：
                                        直线段最坏滚动和 = 264
                                        葫芦圈段     ≥ 数千
                                     阈值 1000 → **安全边际 3.79 倍**，直线 0 误触发。
                                     ★若"该进圈时 IG 没变 1" → 调小（比如 700）；
                                       "直线/直角弯处 IG 乱变 1" → 调大（比如 2000）。 */

/* ★★★ 2026-09-26 【新】进圈之后的【保持】阈值（迟滞），修 IG 疯狂抖动 ★★★
 *
 * 【实车证据 FW:0926-G10】整趟日志里 `GOURD-ENTRY mark set` / `mark cleared`
 *   交替出现 **20 次以上**，每 50~100mm 就翻一次。IG 是下面四件事的总闸门：
 *     ① 出圈右转的闸门   ② 出圈锁存
 *     ③ 圈内丢线屏蔽     ④ 我 09-26 加的"圈内 sp 不许切直道速度"
 *   IG 抖动 ⇒ 这四件事全都只在一半时间生效（等于都没生效）。
 *
 * 【为什么会抖 —— 上面那条 3.79 倍边际不成立】
 *   清印记的路在 `if (ig_now) ... else { ... }` 的 else 里：
 *     连续 GOURD_ENTRY_CLEAR_FRAMES(20) 拍 `ge_is_plain_line()` 为真 → 清。
 *   **而葫芦圈的圆弧上，位图经常就是一路普通的 2 路图案（00011000/00001100）**
 *   —— 这正是"相切点在 IR 上不可见"的同一件事的另一面：
 *     圆弧的线看起来跟直道的线一模一样 ⇒ `ge_is_plain_line()` 在圈里**照样为真**。
 *   于是只要 `ig_now` 掉一下（|GZ| 均值在 100 附近来回穿），
 *   200ms 后印记就被清掉 → 下一段又满足进圈条件 → 再 set … 无限抖。
 *   FW:0926-G10 实测 |GZ| 在圈内就在 40~150 之间晃 ⇒ 10 拍均值刚好卡在阈值上。
 *
 * 【修法：迟滞（进圈难、出圈更难）】
 *   已经 IG=1 时改用本阈值 —— 只要还有"在转弯"的迹象就继续续命。
 *   进圈阈值**完全不动** ⇒ 直线/S 弯/直角弯的误进圈行为与现在一模一样（零风险）。
 *   取 400（= 10 拍均值 |GZ| ≥ 40°/s）：
 *     · 圈内实测均值 ~50~100 → 稳稳保有 ✓
 *     · 普通直道 |GZ| 均值 ~10~30 → sum 100~300 < 400 → 该出圈时照样能出 ✓
 *   ★回退：把 line_follow.c 里的迟滞判断删掉即可（或把本值改成 = 1000）。 */
#define GOURD_IG_HOLD_TH     400

/* ★★★ "车确实在跑"的前置条件（2026-09-23 实车数据驱动）★★★
   实车证据（FW:0923-3200 起步日志）：
       拍1 ST=2 RPM1=22      ← 刚起步（PWM≈6，几乎没动）
       拍2 ST=2 RPM1=-17251  ← 编码器毛刺
            GOURD-ENTRY mark set (in gourd)   ← ★就在这一拍误点了火
   原因：起步瞬间陀螺仪暂态(GZ=141/-78) + 编码器毛刺，把窗口和凑够了 1000。
   → 加这个条件：**只有至少一个轮子转速 >= 此值，才把 |GZ| 喂进窗口**。
      静止/刚起步 → 不喂 → 窗口自然衰减到 0 → IG 保持 0 ✓
      真正在跑   → 车速 100+ RPM，远超它 → 正常喂 → IG=1 ✓
   取 60：起步 PWM≈6 时约 22 RPM（不够），正常巡线 100+ RPM（远超）。
   ★若"低速过葫芦圈时 IG 不亮" → 调小（比如 40）。 */
#define GOURD_IG_MIN_RPM     60

/* ★屏蔽期间"冻结的 error"用多大：
   0 = 用丢线前一拍的 last_error（推荐，方向最真实）
   其它值 = 强制用这个误差值（例如 +3 = 一直轻微右偏，适合"出圈就该往右"） */
