/* ★★★ 2026-10-08（1008-R22）【出圈：里程窗口 + T 形图案】判据⑤ ★★★
 *  【几何（用户拍照确认）】葫芦圈出口是一个【T 形三岔】：一条笔直的出口线
 *    **垂直**落在圈线（圆弧）上，交点就在圆弧最高点，圆弧左右都继续延伸
 *    ⇒ **线不会消失，车顺着圆弧当然能接着走** —— 这才是它一直绕圈的真正原因。
 *    （所以旧判据②"圈内持续丢线 = 出口"对不上这个几何；R18 那趟我看到的 IR 全灭
 *      是"跑完之后丢线原地转"，不是 T 形口 —— 那次判断我做错了，记在这里以免重犯。）
 *  【判据⑤】里程窗口 + 图案，两个【同时】满足才转：
 *      ① 里程落在 [GOURD_EXIT_WINDOW_MM ± GOURD_EXIT_WIN_HALF] 内；
 *      ② 看到 T 形候选图案（当前拍位图 【或】 1kHz 窗口里最宽的那张位图）。
 *    为什么两个都要：单用里程怕刻度漂（你们踩过"6900 在圈中途触发"）；
 *      单用图案怕别处误命中（0924"走两步就右转打死脱线"就是这么来的）。
 *    1kHz 那一路是"太快看不到"的正解：100Hz 会整拍跳过一个只闪 1~2 拍的图案，
 *      1kHz 的 maxraw 抓得到（那个窗口由相切点识别处取走并缓存在 s_1k_maxraw）。
 *  【本版先跑"标定"】armed 之后每看到一次候选图案就打一行 "T-CAND"（带里程+位图+是否在窗口内），
 *    最多 GOURD_EXIT_LOG_MAX 行。这一趟跑完就能定下两件事：
 *      · 真正的出口在多少里程 ⇒ 替换 GOURD_EXIT_WINDOW_MM 的占位值；
 *      · T 形图案到底是哪个位图 ⇒ 替换/收紧 GOURD_EXIT_PATTERN。
 *  ★安全设计：GOURD_EXIT_DEADLINE_MM 默认 0（兜底转向【关】）⇒
 *    即使窗口占位值不对，也只会"不转"，绝不会在错的地方乱转。
 *  ★减速（用户方案）本版【不启用】：按约定"先把判据跑通再加减速"，一次只动一个变量。
 *    下一轮开减速时要注意：内轮命令 = sp − corr，太小会被 WHEEL_PWM_FLOOR(20) 抬上去
 *    ⇒ 差速被吃掉 ⇒ 出口前跑不圆。所以减速要温和（24 → 20），不要一步到 12。 */
#define USE_GOURD_EXIT_ZONE    1        /* 1 = 启用判据⑤（里程窗口 + T 形图案）*/
#define GOURD_EXIT_CALIB_ONLY  1        /* ★★★ 标定模式（1008-R23）：只记录、**绝不转向** ★★★
                                           R22 的教训：我让占位窗口 12500 落在了可触发的范围内 ⇒
                                           车在葫芦圈【中途】看到一个 11000000（左弯边缘的假图案）
                                           ⇒ 误判成出口、右转一次 ⇒ s_gourd_done=1 ⇒ 里程闸门关闭
                                           ⇒ 分支口不再接管 ⇒ 切点过不去、一直绕第一圈 ✗✗✗
                                           ⇒ 所以标定期间必须把"转向"这条路彻底切断：
                                              1 = 只把候选图案记进 RAM（我读芯片取），永不转向；
                                              0 = 正常判据（标定完成后再改 0）。
                                           ★这就是"先测后打"的正确做法，别再让占位值参与决策。 */
#define GOURD_EXIT_WINDOW_MM   12500    /* ★占位值（待标定）：起点 → T 形口的总里程 */
#define GOURD_EXIT_WIN_HALF    250      /* 窗口半宽（±250mm）*/
#define GOURD_EXIT_PATTERN     0x0003u  /* ★占位值（待标定）：T 形候选 = 只有最左 2 路亮 */
#define GOURD_EXIT_LOG_MAX     24       /* 标定用：RAM 里最多存几条候选记录 */
#define GOURD_EXIT_DEADLINE_MM 0        /* 兜底：里程 ≥ 窗口+此值时无条件右转。0 = 关（本版）*/
#define GOURD_EXIT_SLOW_EN     0        /* ★R35：关掉（用户要求"先关减速看看车速是不是它拖的"）。R29 的实现有缺陷：里程过 10679 之后【整趟剩下的路】都用 20 ⇒ 只要赛道后半段在 10.7 米之后，车就一直慢。等确认完再按"只在葫芦圈那一段"重开。 */
#define GOURD_EXIT_SLOW_PWM    20       /* 减速后的速度基准：24 → 20（降 17%，即用户说的"降个 80%"）*/
#define GOURD_EXIT_SLOW_MM     800      /* 保留：旧算法用，现已不参与（减速起点改用下面的 GOURD_SLOW_FROM_MM）*/
#define GOURD_SLOW_FROM_MM     10679    /* ★R29b：减速起点 = 【用户实车标定的那个里程数】10679mm（他发车到"干扰结束处"停下的读数）。不是闸门值 10700，也不是"过了直角弯"这种描述。*/      /* 提前多少 mm 开始减速 */
#define BRANCH_EDGE_SIGN        1     /* ★方向符号（±1）：行为反了就改 -1 */

/* ★★ 2026-10-08（1008-R8）【两道防抖 —— 治"有时过有时不过"】★★
   为什么必须加："左右交替"是【计数式】的、没有任何反馈：
     多触发一次 / 少触发一次 ⇒ 后面每个相切点的分支全反过来 ⇒ 表现就是"有时能过有时不能过"。
   ① 连续 BRANCH_EDGE_CONFIRM 拍都满足才算（防单拍毛刺）；
   ② 与上一次触发至少隔 BRANCH_EDGE_MIN_MM 里程 —— 思路照抄本项目对"相切点计数"的处理
      （GOURD_WAVE_MIN_MM = 200mm），文档原话：
      "误报是成簇的：一次真实宽图案被判成 2~3 个相切点"。
   ★相邻相切点之间有约 940mm（R=300 的半圆），250mm 远小于它 ⇒ 不会挡住真事件。
   ★回退：两道都设 0（= 1008-R7 行为）。 */
#define BRANCH_EDGE_CONFIRM 1     /* 连续几拍满足才认（0 = 不确认）*/
#define BRANCH_EDGE_ERR_MAX     8    /* ★R50（用户同意，也是他最早的原话"转向差速要连续变化、不要突变"）：接管时误差的绝对值上限。证据：失败趟接管那一下 es=±12~13 ⇒ cor=-24~31 ⇒ 左轮被命令 -25（原地左转）⇒ 直接把车甩出线（随后 IR 全灭）。方向是对的（第 7 个该往左 ✓），力度太大 ✗。夹到 8 ⇒ cor ≈ 18，是"明确的左/右转"而不是"原地转"。★若发现切点转不够、切不过去 ⇒ 加到 10。 */
#define BRANCH_EDGE_DARK_EXIT   15    /* ★R49（用户同意）：接管期间"全灭"连续这么多拍（15拍=150ms）就【立刻退出接管】。证据：失败趟 T106 接管后线立刻全灭（IR:00000000），可分支口模式还挂着 600ms 硬转（PWM=-18/51 的猛左转）⇒ 车被带出线外、僵在原地。退出后交给丢线兜底（R48：全灭1秒⇒原地旋转找线）。 */
#define BRANCH_EDGE_MIN_MM      300  /* ★R43b：330 -> 300。台账里真实切点最小间距 = 328 ⇒ 330 会误伤真切点；重复那次恰好 250 ⇒ 300 正好挡住它、放行 328+。 */

/* ★★★ 2026-09-24 晚【新】绕圈脱困：用"带符号偏航积分"代替 IR 图案找相切点 ★★★
   实车日志（FW:0924-2323，第 2 个圈绕圈）：
     OD 2799→3209 共 1240mm，IR 恒为 00110000/01110000，GZ 全程同一符号
     (23,54,23,148,109,94,86,156,117,54,7,62,109,78,141,109,101,47)
     → 车在一个圆上绕了约 2 圈，而这 1240mm 里【一次宽图案都没出现】。

   ★几何原因（这条最关键，它解释了为什么之前所有靠图案的尝试都必然失败）：
     两个【外切】圆在相切点处【共用一条切线】→ 走线在那里是 C¹ 连续的，
     只是曲率换号。传感条看到的是一条【普通、光滑的线】：
     不变宽、不分叉 ⇒ 用 IR 图案【根本不可能】识别相切点 ✗✗✗
     （日志实证：绕了 2 圈，零次宽图案）

   ★能用的信号只有"转过的角度"：
     · 葫芦圈是 S 形（左右交替）→ 带符号偏航积分互相抵消 ≈ 0
     · 绕圈是单方向     → 积分一路累加到 ±180° 以上
     而相切点在几何上【正好】出现在"同方向转够约半圈"的位置（曲率换号处）。

   ⇒ 判据：同号偏航累计到 GOURD_ARC_FLIP_MDEG → 强制朝【反方向】打舵，
     打完就把积分清零，等下一次同号累计 —— 即"每到半圈就换向"。
     方向取自【当前误差的反面】(不依赖陀螺/电机符号约定，无需标定)。
   回退：改 0。 */
/* ★★★ 2026-09-26 打开（=1）—— 这是【第四条路线】，前三条已全部被证伪 ★★★
 *
 * 【为什么换到这条】葫芦圈问题上已经失败三次，而且三次都是同一类做法：
 *     ① 相切点直行窗口        (9-24)  ✗ 更差（第 1 圈就绕）
 *     ② GW 计数触发出圈        (9-24)  ✗ 走不了葫芦圈
 *     ③ 直行窗口 + 宽度上限    (今天)  ✗ 触发 13→20 次，绕圈更多
 *   根本原因（见 文档/相切点为什么IR识别不了-几何结论-20260924.md 第 3 节）：
 *     **两个外切圆在相切点共用一条切线 → 走线 C¹ 连续、线不变宽也不分叉**
 *     ⇒ 相切点在 IR 上【不可见】⇒ **任何"等 IR 出现某个特征再动作"的方案都不可能成功**。
 *   本方案【不看 IR】，改用带符号偏航积分 —— 绕开了那个几何障碍。
 *
 * 【前提已修】它依赖陀螺积分不失真。原 ±1000dps 档实测削顶 7.4%
 *   （GZ=-995 出现 25 次）→ 积分会少算 → 阈值永远到不了。
 *   已把 imu.c 的 GYRO_CONFIG 改到 ±2000dps（见那里的长注释）。
 *   ★所以本开关与 imu.c 的量程改动必须【配套】，单独开一个没用。
 *
 * 【判据（跑车时看什么）】
 *   · 事件行 `GOURD-ARC: flip dir=±1 OD=xxxx GW=x`
 *       - 葫芦圈段应出现 **3~5 行**（每个相切点一行）→ 判据成立
 *       - 一行都没有 → 偏航积分仍没到 170°（可能仍削顶，或阈值偏大）→ 调 GOURD_ARC_FLIP_MDEG
 *       - 出现很多行且车抖 → 阈值太小，普通圆上也在翻 → 调大 MDEG
 *   · 现象：不应再"锁在一个圆上绕圈"，葫芦圈段里程应显著下降（基线 9331mm）
 *   · 回退：改 0（行为回到 0926-1715 基线） */
/* ★2026-09-26 16:0x 【实测失败，已关回 0】★★
 *   配套的陀螺量程改动（imu.c 0x10→0x18）实车把 IMU 弄坏了：
 *     整趟 `GZ=0`（恒为零，从 ST=1 到结束），`K1` 从正常 0~10 涨到 20~30
 *     （主循环被拖慢），左轮 RPM1 长时间 0~5。
 *   ⇒ IMU 初始化异常 + 主循环延迟。该量程改动已 git revert。
 *   ⇒ 本开关依赖陀螺，陀螺坏着的时候开着只会有害，所以同步关回 0。
 *   ★教训：改 IMU 量程这类"影响所有 GZ 使用者"的参数，必须先单独验证
 *     "GZ 读数还正常"，再谈依赖它的功能 —— 不能一次改两个东西。
 *   想再试：先把陀螺读数的修复单独做出来并验证（GZ 不再恒为 0），再打开本开关。 */
/* ★★★ 2026-09-26 晚【重新打开，并修掉两个让它一直没生效的 bug】★★★
 *
 * 【为什么敢再开】陀螺现在是好的（FW:0926-FILT 全程 GZ 正常跳动，
 *   不再是恒 0），而且 ±1000dps 档不削顶（SAT=0）—— 原来的两个前提都成立了。
 *   另外编码器滤波真修好后，速度环不再吃垃圾反馈，车的基础行为已明显改善
 *   （用户："好多了"）。
 *
 * 【用户实测现象（决定性）】问出来的两个答案：
 *   · "在同一个圆上一直绕（比如最下面那个大圆），反复绕同一个，转不出来"
 *   · "一直往右（顺时针）"
 *   ⇒ 车【经过了相切点却没有换向】：在圆 1 上一直右转，到切点本该改成左转，
 *     它继续右转 → 回到同一个圆 → 无限循环。
 *   ⇒ 这正是本机制要治的病，而且现在的现象描述与判据完全对得上。
 *
 * 【Bug 1（致命）：累加器被"出圈"清零 → 阈值永远到不了】
 *   原代码：`if (!ge_in_gourd) { s_arc_mdeg = 0; ... }`
 *   而 IG（在圈判定）本来就在抖（日志里 GOURD-ENTRY mark set/cleared 反复交替）。
 *   每闪一下，辛苦攒的偏航就被抹掉 → 到不了 170° → 【机制从未触发过】。
 *   ⇒ "关了它"和"它没用"是两件事，它根本没运行过。
 *   修法：加【出圈保持】—— 离开葫芦圈要连续 GOURD_ARC_EXIT_HOLD 拍才复位。
 *
 * 【Bug 2：打舵方向取错了】
 *   原代码：`s_arc_dir = (last_error > 0) ? -1 : 1;`（取【当前线位置】的反面）
 *   但相切点处线是 C¹ 连续的、车此刻基本居中（|e| 很小），
 *   用线位置取反在某些相位会【顺着原来的转向推】→ 锁得更死。
 *   正确依据是【车实际在往哪边转】= 偏航累计的符号：
 *     imu.c 约定 gz > 0 = 左转。往右绕 → mdeg < 0 → 要往左推 → e > 0 → dir = +1
 *     ⇒ dir = (mdeg < 0) ? +1 : -1
 *
 * 【阈值 170° → 320°】原值"约半圈"是按"S 形穿过、相切点在半圈处"设的；
 *   但真实几何（见轨道照片 + 用户观察）是【每个圆独立绕一圈】，
 *   所以要凑满【几乎一整圈】(320°) 才判定"它锁死了"，否则每个圆上都会误触发。
 *
 * 【判据（跑车时看什么）】
 *   · 事件行 `GOURD-ARC: flip dir=±1 mdeg=±xxxxx OD=x GW=x`
 *     - 出现 → 机制在跑（这是第一次真正跑起来）
 *     - 一次都没有 → 累计仍被清零，看 GOURD_ARC_EXIT_HOLD 是否需要加大
 *   · 现象：不再"在一个圆上反复绕"；葫芦圈里程应显著下降
 *   · 回退：GOURD_ARC_FLIP 改 0
 *   · 若车"每绕一圈就抽一下、宁可不过也别抽"→ 把 PUSH/MAX 调小
 *     （PUSH 8→5、MAX 40→25） */
#define GOURD_ARC_FLIP        0        /* ★★★ 2026-09-26 晚【关掉 —— 这条路线被实车否定】★★★
                                          ★四版实测的完整结论（三次不同阈值，两次方向相反地失败）：
                                            阈值 320000(320°):  AN=0  → 从不触发
                                              （累计峰值只有 123°，永远等不到）
                                            阈值 150000(150°):  AN=4  → 触发但"转向过头"
                                              （相切点约在 AR 95~105k，触发时已 152k = 太晚）
                                            阈值  90000( 90°):  AN=5  → "过圆环时转向很糟糕"
                                              （正常绕圈也会累计到 90° → 每圈都误触发，
                                                每次触发后车立刻丢线，连续 IR:00000000）
                                          ★★为什么"没有阈值能work"（原理性结论，别再试）★★
                                            车在【正常绕圈】与【卡住】两种状态下，
                                            偏航累计的数值范围【重叠】—— 
                                              · 调高阈值 → 抓不到"卡住"
                                              · 调低阈值 → 每圈正常转弯都被打舵
                                            ⇒ 这个信号里根本不含"我卡住了"这个信息。
                                              我之前假设"绕圈必然累计到 360°"是错的
                                              （实测峰值 123~152°，它自己会缓下来）。
                                          ★副作用（真实且严重）：每次打舵后车会丢线
                                            （400ms 硬打舵把它推离线）→ 再花几百 mm 找回来，
                                            净效果比不打舵更差。A90 那趟只到 OD 4634 就卡死。
                                          ★教训：**"能观测"不等于"能判别"。**
                                            我先证明了 AR 可观测（AN 终于非 0），
                                            但没验证它能否【区分】两种状态就上了车。
                                          ★要重开：先把 GOURD_ARC_FLIP_MDEG 设回 150000，
                                            并先把"打舵后丢线"这个副作用解决（缩小 PUSH/MAX）。 */
#define GOURD_ARC_FLIP_MDEG   150000   /* 保留 150° 作为将来重开的起点（见上） */
#define GOURD_ARC_FLIP_PUSH   8        /* 反向打舵量（误差单位；×KP2.0 = 20 PWM）*/
#define GOURD_ARC_FLIP_MAX    40       /* 反向打舵拍数（100Hz → 400ms）*/
#define GOURD_ARC_DB_DPS      15       /* 陀螺死区(dps)：以下不计入积分，只缓慢衰减 */
#define GOURD_ARC_EXIT_HOLD   100      /* 离开葫芦圈要连续这么多拍(1s)才复位偏航累计 */

/* ★★★ 2026-09-24 晚【用户判断】葫芦圈里没有十字路口 ★★★
   用户原话："葫芦圈里是没有十字路口的，所以当识别到葫芦圈后，
             后续判断疑似十字路口的都当葫芦圈处理"
   ★日志正好支持这个判断（FW:0924-2323）：
     CROSS #1 IR=11111111 e=+0 wide=2 (straight)   ← 判成十字 → 强制直行
     CROSS #2 IR=11100011 e=-3 wide=2 (straight)
           IR=10000001
           IR=00000000                            ← 紧接着丢线 ✗
           IR=00000000
   圈内那些"疑似十字"其实是【葫芦圈与外面赛道的连接口(T/Y 型)】，
   在那里【该顺着线转弯】，强制直行必然冲丢线；
   更糟的是它很可能把车【送上圈的错方向】→ 之后才开始绕圈。
   ⇒ 圈内(ge_in_gourd)一律【不按十字处理、也不按"宽图案过久"处理】，
     交回普通 PD 循迹（该转就转）。
   注意：这道门依赖 IG 判定，而 IG 现在一次跑会翻 30+ 次
        —— 圈外被误判进圈时，只是"该直行的十字变成跟线走"，不会更糟。
   回退：改 0。 */
#define GOURD_NO_CROSS        1

/* ★葫芦弯相切点状态机（2026-09-22 他提的方案）
   原理：4 个外切圆之间有 3 个内部相切点，每过一个转向要翻转；
        接近相切点时，下一个圆的弧先从传感条【边缘】出现，再往中间扩散 → "外→内"波。
   做法：检测"最外路亮(≤2路) → 3 拍内扩散到 ≥3 路" = 相切点；
        记一次；丢线时按【翻转后的方向】修正（而不是沿用上次方向）；
        累计 3 次 = 绕完 4 个圆 → 退出。认不出来就照常循迹（兜底不变）。 */
#define USE_GOURD_SM         1
#define GOURD_EDGE_WINDOW    3           /* 最外路亮之后, 多少拍内扩散算一次波 */
#define GOURD_TOTAL          3           /* 相切点个数（4 个外切圆 → 3 个） */
#define GOURD_FLIP_CYCLES    15          /* 检测到相切点后, "翻转修正"保持的拍数 */
#define GOURD_FLIP_ERR       3           /* 翻转修正用的误差幅度 */
/* ★2026-09-22 按实测数据定：车靠通用 PD 就正确进了下一个圆 → "翻转转向"默认关掉
   （强行翻转会把已经走对的车推歪）。
   ★★★ 2026-09-24 晚【打开 = 1】—— 因为上面那条前提已经不成立了 ★★★
     实车现象（用户原话）："绕着第 1 个葫芦圈转了两圈差不多"
     —— 车进了圈就【锁在第 1 个圆上绕圈】，根本没走到出口。
     上一版"感觉能过"是 KP=3.0 时；降到 2.5 后转不过相切点了（转向力度不够）。
     ⇒ "纯 PD 能进下一个圆"这个前提失效，所以关掉它的理由也失效。
     ★翻转修正的机理：相切点处走线要从圆 1 跨到圆 2，而圆 2 的曲率方向与圆 1 相反；
       PD 只顺着最强的那条线走 → 永远绕同一个圆。翻转 = 命中相切点后把误差取反
       若干拍，强制车头拐向另一个圆。
     ★安全：它的触发点已挪进 `if (ge_in_gourd ...)` 门里（line_follow.c），
       圈外（直角弯）误命中不会让车反向修正。
     ★若实车发现"更糟 / 被推歪"→ 改回 0（这条是实测过的风险，别硬撑）。
     想试别的力度：GOURD_FLIP_CYCLES（保持拍数 15）与 GOURD_FLIP_ERR（误差幅度 3）。 */
#define GOURD_USE_FLIP       0
/* ★★★ 是否让翻转修正在【正常循迹路径】上生效（2026-09-24 晚新增，默认 0）★★★
   0 = 只在"短暂丢线 / 宽图案持续过久"两个分支里生效（= 历史行为，实车上基本等于没生效）
   1 = 正常路径也覆盖 e（2026-09-24 晚试过一次，实车结果"没有效果 + 摆头更厉害"，已回退）
   ★要再试 1 的前提：先把【触发时机】做可靠 —— 翻转的门是 ge_in_gourd(IG)，
     而 GOURD_IG_SUM_TH=1000 是陀螺量纲修好【之前】定的，IG 会误触发；
     误触发一次 = 给车 15 拍错误的反向修正 = 摆头。
   ★这也解释了 09-22 原作者"翻转没用、还更糟"的结论：
     它当时在这条路径上就没生效过，能看到的效果只有误触发带来的副作用。 */
#define GOURD_FLIP_ON_NORMAL 0

/* ★弯道计数 → 强制右转（2026-09-22 他提的方案：不比特征，直接数"最右一路"被触发几次）
   思路：数 bit7（最右那一路）被触发的次数，数够 N 次就强制右转 + 串口打印"出葫芦弯道"。
   ⚠️ 三个前提（改之前先读，否则这个计数器会骗你）：
   1) **必须按"上升沿"计数**（上一拍暗→这一拍亮），不能"每拍累加"：一次持续点亮会被算成
      几十次，而且绑死 10ms 拍/速度（= test161 那个老坑）。代码里已经是边沿计数。
   2) `G7_LOCKOUT`：两次计数之间至少隔几拍，防抖/机械回弹把一次点亮算成多次。
   3) `G7_TURN_TRIG` 的 12 是**拍脑袋值**：★先跑一圈，看遥测 `G7=` 在葫芦出口读到多少，
      再把这个数改成实测值。12 现在没有数据支撑。 */
#define USE_G7_COUNT         1      /* 1=数最右一路(bit7)的触发次数（诊断用，建议一直开着） */
#define G7_LOCKOUT           3      /* 两次计数之间至少间隔的拍数（3 拍 = 30ms） */

/* ★2026-09-23 又改回 0：【实车证据】它是一次失败的直接原因。
   实车日志（FW:0923-3000）末尾：
       `GOURD EXIT (G7 count) -> FORCE RIGHT`   ← 本机制触发
       → IR:10000000  RPM1=213 RPM2=0            ← 右轮停转的硬右转
       → IR:00000000  GZ=-1990                   ← 全灭 + 陀螺仪饱和(>2000°/s)
       → 车疯狂旋转，线再也找不回来
   为什么它不该开：触发条件是"数最右一路被触发 12 次"，而那个 12 是【拍脑袋值】
   （本文件下面注释自己写着"没有数据支撑"）。而同一个葫芦圈里，**纯 PD 已经自己
   走完了约 60 拍、位图一路正常** —— 说明 PD 本来不需要它，它只会在错误位置插一脚。
   ★真正该做的是靠 GOURD_EXIT_*（角速度/距离/拍数 三重判据），不是这个旧机制。 */
#define USE_G7_TURN          0      /* 0 = 关闭（当前）。要试旧机制再改回 1 */
#define G7_TURN_TRIG        60000     /* ★触发阈值（他给的 12，待实测修正） */
#define G7_TURN_FRAMES       50     /* 硬转保持的拍数（25 拍 = 250ms） */
#define G7_TURN_PWM          41     /* 硬转时的差速幅度（sp_curve ± 此值，左快右慢=右转）
                                       ★2026-09-23 12V: 55×0.74 = 41 */
/* ★保险闸：数到阈值后【不立刻转】，而是等"分支口特征"（宽图案 ≥G7_GATE_WIDE_MIN 路
   且 只贴一端、另一端空）出现的那一拍再转 —— 防"数到 12 时正好在直道上"→ 一把拐出赛道。
   0 = 纯计数触发（他原本的方案）；1 = 等分支口确认（安全，默认）。
   被闸门挡住时会打印一次 `G7 HIT but not BRANCH`，一眼看出"数够了、但位置不对"。 */
#define G7_TURN_GATE_BRANCH  1
#define G7_GATE_WIDE_MIN     5      /* 闸门用：判"宽图案"的路数门槛（同 CROSS_ACTIVE_MIN） */

/* ---------------------------------------------------------------------------
 * 三、循迹通道表 —— 8 路红外(数字量, GPIO 读)
 *  ★ 权重 = 传感器"物理位置"的等比排布：-7 -5 -3 -1 +1 +3 +5 +7
 *    （2026-09-20 按他实测"居中时中间两路同时触发"定的表；中间的 0 由 -1+1 自然得到）
 *  ★ 引脚: PA0 PA1 PA8 PA15 PB0 PB1 PB12 PB13（左→右）
 *    物理引脚已在 CubeMX 配成 GPIO 输入（gpio.c），这里只放逻辑表。
 * -------------------------------------------------------------------------*/
#define LINE_CHANNELS        8

typedef struct {
  GPIO_TypeDef* port;
  uint16_t      pin;
  int8_t        weight;
} line_channel_t;

#define LINE_CHANNEL_TABLE \
  { GPIOA, GPIO_PIN_0,  -7 }, \
  { GPIOA, GPIO_PIN_1,  -5 }, \
  { GPIOA, GPIO_PIN_8,  -3 }, \
  { GPIOA, GPIO_PIN_15, -1 }, \
  { GPIOB, GPIO_PIN_0,  +1 }, \
  { GPIOB, GPIO_PIN_1,  +3 }, \
  { GPIOB, GPIO_PIN_12, +5 }, \
  { GPIOB, GPIO_PIN_13, +7 }

/* ---------------------------------------------------------------------------
 * 四、电机转向映射
 *  电机1 = 左轮 PWM=PA2(TIM2_CH3) DIR1=PA4 DIR2=PA5
 *  电机2 = 右轮 PWM=PA3(TIM2_CH4) DIR3=PB3 DIR4=PB4
 *  ★2026-09-20 新车实测：串口 T 指令给正数时【两个轮子都朝后转】
 *    → 两个都置 1 反转（只改"正数=前进"的约定，不动接线）
 *    换驱动板/重新接线后如果又反了，改这两个宏即可（不用动 motor.c）
 * -------------------------------------------------------------------------*/
#define MOTOR_LEFT_INVERT    1
#define MOTOR_RIGHT_INVERT   1

/* ---------------------------------------------------------------------------
 * 五、编码器（USE_ENCODER=1 时）
 *  ★ 左编码器 → TIM3 编码器模式(PA6=CH1, PA7=CH2)
 *    右编码器 → TIM4 编码器模式(PB6=CH1, PB7=CH2)
 *  ★ PPR：EncoderMode_TI12 = 4 倍频（CH1/CH2 的上升+下降沿都计数）
 *    输出轴每圈脉冲 = 编码器基 PPR 11 × 减速比 9.6 × 4 ≈ 422
 *    → 装好后手转一圈核对：ENC1 计数应变化约 ±422。
 * -------------------------------------------------------------------------*/
#define ENCODER_PPR           422

/* ===========================================================================
 * ★★★ 左右轮【方向符号】—— 2026-09-23 实车抓到的关键 bug ★★★
 *
 *  现象（用户实测）：架空后单独转两个轮子，**里程互相抵消**，OD 几乎不涨。
 *
 *  原因：正交解码的方向取决于 A/B 相【接线】。若某一轮 A/B 接反，
 *        车往前走时那一轮计数是【减少】的。而
 *            odom.c: step_um = (d_l + d_r) * 491 / 2
 *        —— 一正一负正好**抵消** → 里程永远上不去。
 *        剩下的只有 (d_l - d_r)/2，而它正比于"车【转】了多少"，
 *        不是"走了多远"。所以当时读到的 403/400mm **根本不是里程**。
 *
 *  ★★ 最终修法：里程改成"取绝对值"，**不再依赖符号** ★★
 *     odom.c 里车体前进量改成 (|d_l| + |d_r|) / 2 ——
 *     与接线方向完全无关 → 不用标定符号，也不会再猜错。
 *     ★修好后实测：发车 → 葫芦圈出口 的全程 = **24847mm**。
 *     所以下面这两个符号**现在只影响遥测里的 L= / R= 读数**，
 *     不再影响车体里程（OD= / PATH=）。
 *
 *  ★这两个符号怎么定（可选，只是为了 L=/R= 好读）：
 *      1. 把车放地上，串口发 Z 清零
 *      2. 用手把车【整体往前推 20~30cm】（两个轮子一起往前滚）
 *      3. 串口发 O → 看 L= 和 R=
 *         · 两个同号 → 符号对了（方向一致）
 *         · 一正一负 → 把其中一个改成相反的
 * ===========================================================================*/
#define ODOM_SIGN_L           (+1)   /* ★只影响遥测 L= */
#define ODOM_SIGN_R           (-1)   /* ★只影响遥测 R= */

/* ---------------------------------------------------------------------------
 * 六、MPU6050（USE_IMU=1，2026-09-22 已启用）
 *  ★★ PB10/PB11 上是 **I2C2**（不是 I2C1！I2C1 在 PB6/PB7，已被编码器占）
 *    驱动手写在 Core/Src/i2c.c（不经 CubeMX），MspInit 里配 PB10/PB11 为复用开漏
 * -------------------------------------------------------------------------*/
#define IMU_I2C_ADDR          (0x68 << 1)
#define IMU_I2C_TIMEOUT       5           /* ★I2C 超时(ms)：原来是 50ms，线路不好时会把 10ms 主循环拖到 20Hz */

/* ---------------------------------------------------------------------------
 * 七、人机：三灯 + 蜂鸣器 + 启动键（2026-09-20 按实物接线定稿）
 *  ★ LED 实物接法 = 端口 → LED → 1k → GND（三颗都是），所以【高电平点亮】
 *    灯珠长脚(正)朝端口侧、短脚朝 GND 侧；0603 1k 串在线里。
 *  ★ 蜂鸣器 = 无源(从 MH-FMD 模块上拆下的元件)，PA11 = TIM1_CH4 PWM，
 *    板上 SS8050 低边驱动 + 1N4148W 续流；原设计 2.7kHz（新件谐振约 4kHz，不够响改 4000）
 *  ★ 启动键 = PB9，按下接地（上拉已在 gpio.c），软件消抖 30ms
 * -------------------------------------------------------------------------*/
#define LED_ON_LEVEL         GPIO_PIN_SET      /* 高电平点亮 */
#define LED_OFF_LEVEL        GPIO_PIN_RESET
/* ★2026-10-22 晚【跑车时 LED3 是否常亮】—— 他："这破灯一直常亮我看啥？？"
   就是这里：进入 CAR_RUN 时 `led_set(LED_ID_3,1)` 把第三灯钉亮；之后除了"事件拍"没人再写它 ⇒ 一直亮着。
   ⇒ **0 = 跑车时三灯全灭**，只有事件才亮（IG 闪一下 / 出口闪 / 丢线 LED2 闪）。
   ★回退：改 1。 */
#define RUN_LED3_ON          0

#define BUZZER_FREQ_HZ       2700u             /* 蜂鸣器 PWM 频率 */
#define COUNTDOWN_BEEP_MS    120u              /* 读秒每步"哔"的时长 */
#define COUNTDOWN_STEP_MS    1000u             /* 读秒每 1s 亮一颗灯（比赛计时从发令算，想省时间改这里） */
#define KEY_DEBOUNCE_TICKS   3                 /* 30ms 消抖（UI_PERIOD_MS × 3） */
#define KEY_LONG_PRESS_MS    1000u             /* 长按 1s = 急停 */

#endif /* APP_CONFIG_H */
